    // 延迟执行，确保所有脚本加载完成
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', function() {
        setTimeout(function() {
          window.gaDebug.check();
        }, 1000); // 延迟 1 秒确保 GA 脚本完全加载
      });
    } else {
      setTimeout(function() {
        window.gaDebug.check();
      }, 1000);
    }
  }

})();

