### 💡 实战案例：FAB 浮动按钮菜单

```tsx
import React, { useState } from 'react';
import { Menu, MenuItem } from '@xiaorunbao/react-rainbow-menu';

// 移动端常见的浮动操作按钮（FAB）实现
function FloatingActionButton() {
  const [show, setShow] = useState(false);
  const [position, setPosition] = useState({ x: window.innerWidth - 80, y: window.innerHeight - 120 });

  return (
    <div style={{ position: 'relative', width: '100vw', height: '100vh' }}>
      {/* FAB 按钮 */}
      <button
        onClick={() => {
          // 动态计算按钮位置（右下角）
          setPosition({
            x: window.innerWidth - 80,
            y: window.innerHeight - 120
          });
          setShow(!show);
        }}
        style={{
          position: 'fixed',
          right: '20px',
          bottom: '20px',
          width: '56px',
          height: '56px',
          borderRadius: '50%',
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
          border: 'none',
          color: 'white',
          fontSize: '24px',
          cursor: 'pointer',
          boxShadow: '0 6px 20px rgba(102, 126, 234, 0.4)',
          zIndex: 1000,
          transition: 'transform 0.2s ease'
        }}
      >
        {show ? '✕' : '+'}
      </button>

      {/* 径向菜单 */}
      <Menu
        show={show}
        centerX={position.x}
        centerY={position.y}
        innerRadius={40}
        outerRadius={100}
        animation="scale"
        maxLayers={1}
      >
        <MenuItem onItemClick={() => console.log('新建文件')}>
          📄 新建
        </MenuItem>
        <MenuItem onItemClick={() => console.log('上传文件')}>
          ⬆️ 上传
        </MenuItem>
        <MenuItem onItemClick={() => console.log('搜索')}>
          🔍 搜索
        </MenuItem>
        <MenuItem onItemClick={() => console.log('分享')}>
          📤 分享
        </MenuItem>
      </Menu>

      {/* 点击遮罩关闭菜单 */}
      {show && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0, 0, 0, 0.3)',
            zIndex: 999
          }}
          onClick={() => setShow(false)}
        />
      )}
    </div>
  );
}
```

### 最佳实践

#### 1. 精确居中对齐

```typescript
// 推荐：使用 getBoundingClientRect() 计算精确中心
const handleClick = (e: React.MouseEvent, triggerRef: RefObject<HTMLDivElement>) => {
  if (!triggerRef.current) return;

  const rect = triggerRef.current.getBoundingClientRect();
  const parentRect = containerRef.current?.getBoundingClientRect();

  if (parentRect) {
    const centerX = rect.left - parentRect.left + rect.width / 2;
    const centerY = rect.top - parentRect.top + rect.height / 2;
    setPosition({ x: centerX, y: centerY });
  }
};
```

#### 2. 性能优化建议

```tsx
// 使用 useCallback 避免重复创建函数
const handleItemClick = useCallback((event, index, data) => {
  console.log('Clicked:', data);
  setShow(false);
}, []);

// 合理设置 maxLayers 避免过深嵌套
<Menu maxLayers={2}> {/* 推荐不超过 3 层 */}
```

#### 3. 无障碍访问 (A11y)

```tsx
<MenuItem
  role="menuitem"
  aria-label="保存文件"
  tabIndex={0}
  onKeyDown={(e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      handleSave();
    }
  }}
  onItemClick={handleSave}
>
  💾 保存
</MenuItem>
```

