### 1. 动态菜单项渲染

```tsx
// 根据用户权限动态生成菜单项
function DynamicMenu({ userRole }: { userRole: string }) {
  // 定义不同角色可用的菜单项
  const menuConfig = {
    admin: [
      { id: 'users', icon: '👥', label: '用户管理' },
      { id: 'settings', icon: '⚙️', label: '系统设置' },
      { id: 'logs', icon: '📋', label: '操作日志' }
    ],
    user: [
