      { id: 'logout', icon: '🚪', label: '退出登录' }
    ]
  };

  const items = menuConfig[userRole] || menuConfig.user;

  return (
    <Menu show={show} centerX={x} centerY={y}>
      {items.map((item) => (
        <MenuItem
          key={item.id}
